import{z as o,x as B,o as e,c as n,q as t,j as s,D as E,d as r,s as A,S as l}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"胶去除与灰化","description":"","frontmatter":{"title":"胶去除与灰化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-strip-ash.md","filePath":"litho/resist-strip-ash.md","lastUpdated":1791063341000}'),p={name:"litho/resist-strip-ash.md"};function d(h,a,m,_,c,D){const i=B("Mermaid");return e(),n("div",null,[a[2]||(a[2]=t('<h1 id="胶去除与灰化" tabindex="-1">胶去除与灰化 <a class="header-anchor" href="#胶去除与灰化" aria-label="Permalink to &quot;胶去除与灰化&quot;">​</a></h1><div class="epigraph"><p>转印结束，胶从掩模变成污染物。灰化与湿法剥离要拿得干净，又不能伤已刻的衬底和硬掩模。</p><footer>—— 对照 resist strip / O₂ ash 在图形化后的公开步骤</footer></div><p><a href="/litho/barc-open-etch">上一课</a>仍把胶当掩模。本课是轨道补层最后一课：图形已经在下层，去掉胶和残碳。缺口不是再写显影，而是剥离选择比与残留。后课曝光机子系统从准分子激光另起。工序位置决定合同条款：下层图形已经成形，任何过激化学都是不可回退的损伤，所以剥离窗口永远是「除胶速率」对「衬底损失」的比值游戏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>干法灰化快，但对注入、金属、低 k 可能伤。湿法（溶剂、胺、酸）对硬化、离子注入胶可能去不净。植入后胶「皮」交联，要先灰化再湿法。把残留当「缺陷检测漏检」，会漏掉剥离窗口。</p><p>把受害者点名：FEOL 高剂量注入使胶表面非晶化、碳化成硬壳，溶剂进不去，直接湿法必残留；BEOL 多孔低 k 靠碳桥撑 k 值，O₂ 灰化把碳拔走，k 值与后续刻蚀速率一起漂，损伤不可逆；铝线怕含氯残留引发腐蚀，金属栅与高 k 怕氧化。另一头是去不净：刻蚀过程把胶烧结、侧壁聚合物沉积，普通溶剂剥不动。还有一类新对象——EUV 金属氧化物胶根本不是碳氢网络，O₂ 灰化只剩金属氧化物渣，剥离化学要整个重写（<a href="/litho/euv-resist">EUV 胶</a>）。把残留当成检测的漏检去追，方向就错了：检测看见的是结果，窗口在剥离配方里。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>常见：O₂ 灰化去大部分有机，湿法清灰与金属杂质，再漂洗。含硅 SOG 不能靠 O₂ 当有机胶去。金属氧化物胶要专用剥离，勿套 CAR 灰化。终点：表面亲水、XPS/缺陷可接受、衬底损失在预算内。</p><p>展开成流程：首选下游远端等离子体，O₂（或 O₂/N₂/H₂O 混合）在 150–300 °C 把体胶氧化成 CO/CO₂ 挥发，只留薄层残壳；残壳交给湿法——未硬化 CAR 用 NMP/DMSO 类溶剂，硬化与植入胶用 SPM（硫酸/双氧水，120–150 °C），侧壁聚合物用胺系配方，随后充分漂洗防腐蚀。低 k 层改全湿法或极温和灰化；含硅 SOG 对 O₂ 是「惰性残渣」，要含氟化学单开一条（<a href="/litho/trilayer-soc-sog">三层膜 SOG</a>）。验收走三条线：接触角或 XPS 碳含量卡残留，暗场与电子束复查（<a href="/litho/defect-inspection-optical-ebeam">缺陷复查</a>）卡颗粒，Si 凹陷与氧化层损失卡在埃到纳米的预算内。配方与「下一层是什么」绑定，不是通用耗材。</p>',9)),(e(),s(l,null,{default:E(()=>[A(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MASK%5B%22%E8%83%B6%E4%BB%8D%E5%BD%93%E6%8E%A9%E6%A8%A1%22%5D%20--%3E%20XFER%5B%22%E8%BD%AC%E5%8D%B0%E5%AE%8C%E6%88%90%22%5D%0A%20%20XFER%20--%3E%20ASH%5B%22%E7%81%B0%E5%8C%96%22%5D%0A%20%20ASH%20--%3E%20WET%5B%22%E6%B9%BF%E6%B3%95%E5%89%A5%E7%A6%BB%22%5D%0A%20%20WET%20--%3E%20CLEAN%5B%22%E5%8F%AF%E8%BF%9B%E4%B8%8B%E5%B1%82%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">灰化会氧化衬底表面，金属线可能需要后续还原或清洗。剥离配方与「下一层是什么」绑定。</span></p><p><span class="marginnote">数字实例：若某配方除胶速率 200 nm/min，而衬底氧化损伤折算 0.5 nm/min，选择比是 400:1，预算内；换错配方衬底损失升到 5 nm/min，选择比掉到 40:1——埃级预算里已不可接受。剥离窗口就是这两个速率的比值游戏。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>氧化等离子体把碳氢变成挥发物。交联与植入损伤降低反应速率，留下壳。湿法从壳下钻蚀。选择比来自衬底是否也被氧化或腐蚀。</p><p>补上动力学：灰化速率由氧原子到达率与胶的交联密度共同决定，硬壳段速率掉一个量级，这就是「先快后慢」的终点曲线；湿法剥离靠溶剂从未硬化的底面钻入，把壳整片掀起，所以灰化只负责「破壳」，不负责「除净」，两者边界画错就会出现剥壳不净或钻蚀过度。选择比的化学来源很直接：胶的氧化产物是气体，衬底的「氧化产物」是不可逆损伤——Si 变氧化层、低 k 失碳、铝生腐蚀坑，每一种都有独立的预算行。descum 与本课是同一化学的两端：刻蚀前轻灰去浮渣，转印后重灰清残胶（<a href="/litho/descum">descum</a>）。</p>',5)),(e(),s(l,null,{default:E(()=>[A(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20O%5B%22%E6%B0%A7%E5%8E%9F%E5%AD%90%E5%88%B0%E8%BE%BE%E8%A1%A8%E9%9D%A2%22%5D%20--%3E%20BULK%5B%22%E4%BD%93%E8%83%B6%3A%20%E6%B0%A7%E5%8C%96%E6%88%90%20CO%2FCO2%20%E6%8C%A5%E5%8F%91%22%5D%0A%20%20O%20--%3E%20SHELL%5B%22%E7%A1%AC%E5%A3%B3%3A%20%E4%BA%A4%E8%81%94%2F%E6%A4%8D%E5%85%A5%E6%AE%B5%E9%80%9F%E7%8E%87%E6%8E%89%E4%B8%80%E6%A1%A3%22%5D%0A%20%20BULK%20--%3E%20THIN%5B%22%E5%8F%AA%E5%89%A9%E8%96%84%E6%AE%8B%E5%A3%B3%20%E2%86%92%20%E5%81%9C%E7%81%B0%22%5D%0A%20%20SHELL%20--%3E%20WETNEXT%5B%22%E6%B9%BF%E6%B3%95%E4%BB%8E%E5%A3%B3%E4%B8%8B%E9%92%BB%E5%85%A5%22%5D%0A%20%20WETNEXT%20--%3E%20STRIP%5B%22%E6%95%B4%E7%89%87%E6%8E%80%E8%B5%B7%E5%89%A5%E7%A6%BB%22%5D%0A%20%20WETNEXT%20--%3E%20UNDER%5B%22%E9%92%BB%E8%9A%80%E8%BF%87%E5%BA%A6%20%E2%86%92%20%E6%8D%9F%E4%BC%A4%22%5D%0A%20%20SUB%5B%22%E8%A1%AC%E5%BA%95%3A%20Si%20%2F%20%E4%BD%8Ek%20%2F%20%E9%93%9D%22%5D%20--%3E%20LOSS%5B%22%E8%A2%AB%E6%B0%A7%E5%8C%96%E6%88%96%E8%85%90%E8%9A%80%20%3D%20%E4%B8%8D%E5%8F%AF%E9%80%86%E9%A2%84%E7%AE%97%E8%A1%8C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课结束涂胶显影轨道。不写主刻蚀化学（集成课）。扫描仪光源、物镜、工件台是下一课程。选择比的通用算法留在 <a href="/litho/selectivity-arde">刻蚀选择比</a>与硬掩模课，本课只管「胶已失去掩模价值之后」的清洁合同。</p><p><span class="marginnote">术语翻译：灰化（ash）是用氧等离子体把胶「烧成气体」；descum 是它的轻量版，只去浮渣；SPM（硫酸加双氧水，俗称「食人鱼」）是湿法强氧化剥离。三种都叫除胶，温度与对象完全不同，不能互相替班。</span></p><p><span class="marginnote">常见误区：以为灰化时间越长越保险。体胶去完后，多出来的氧原子全部打在衬底上——低 k 失碳、硅长氧化层、铝生腐蚀坑都在悄悄记账。「先快后慢」终点曲线的拐点就是收手信号。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>剥离是转印后的清洁合同，选择比针对已形成的衬底。</li><li>植入胶、金属胶、含硅层不能共用一条灰化。</li><li>灰化破壳、湿法除净，边界画错就是残留或钻蚀。</li><li>出处：resist strip / ash 通识；接续开口课。</li></ul>',6))])}const f=o(p,[["render",d]]);export{T as __pageData,f as default};
